\subsection{The superspecial K3 surface and the $p>11$ threshold}
In characteristic $p>0$ the most arithmetically extreme K3 surface is the
\emph{superspecial} surface (the supersingular surface of Artin invariant
$\sigma=1$, with N\'eron--Severi rank $22$). Ohashi--Sch\"utt-type analyses show that
the eleven Mukai groups continue to classify maximal symplectic actions on this surface
provided $p>11$. The motivating rigidity statement is the following.

\begin{conjecture}[No non-trivial extension]
Let $X$ be the superspecial K3 surface over an algebraically closed field of
characteristic $p>11$, and let $G\le\Aut(X)$ be finite with $G_s$ maximal (a Mukai
group). Then the period character $\chi$ is trivial; equivalently $[G:G_s]=1$, i.e.
$G=G_s$.
\end{conjecture}

A prerequisite of the classification is \emph{tameness}: that $\#G$ is prime to $p$.
This paper isolates and proves the arithmetic component, and synthesizes it with the
characteristic-$p$ tameness of the non-symplectic index to obtain global tameness.

\section{Definitions}

\begin{definition}[Mukai orders]\label{def:orders}
\[
\mukaiOrders:=[\,960,\,384,\,288,\,192,\,192,\,72,\,72,\,48,\,168,\,360,\,120\,],
\]
the list of orders from Table~\ref{tab:mukai} with multiplicity ($192$ and $72$ each
occur twice). We write $N\in\mukaiOrders$ for membership.
\end{definition}

\begin{definition}[Mukai least common multiple]\label{def:lcm}
\[
\mukaiLcm:=40320=2^{7}\cdot 3^{2}\cdot 5\cdot 7,
\]
whose set of prime factors is $\{2,3,5,7\}$. One checks directly that $40320$ is the
least common multiple of all entries of $\mukaiOrders$.
\end{definition}

\begin{definition}[Symplectic subgroup, non-symplectic index]\label{def:sympl}
For a finite group $G$, a field $k$, and a period character $\chi:G\to k^{\times}$, the
\emph{symplectic subgroup} is $G_s:=\ker\chi$ and the \emph{non-symplectic index} is
$n:=[G:G_s]$; they satisfy~\eqref{eq:factor}.
\end{definition}

\section{Main results}

\subsection{The Mukai least common multiple}

\begin{theorem}[\texttt{mukaiOrder\_dvd\_lcm}]\label{thm:dvd}
For every $N\in\mukaiOrders$ we have $N\mid 40320$.
\end{theorem}

\begin{proof}[Proof sketch]
The claim is a finite conjunction over the eleven entries; each divisibility is a single
integer division with integer quotient:
\[
\tfrac{40320}{960}=42,\ \tfrac{40320}{384}=105,\ \tfrac{40320}{288}=140,\
\tfrac{40320}{192}=210,\ \tfrac{40320}{72}=560,
\]
\[
\tfrac{40320}{48}=840,\ \tfrac{40320}{168}=240,\ \tfrac{40320}{360}=112,\
\tfrac{40320}{120}=336 .
\]
Hence each $N$ divides $40320$.
\end{proof}

Theorem~\ref{thm:dvd} reduces every prime-divisibility question about the eleven Mukai
orders to one such question about the single number $40320$, via transitivity of
divisibility.

\subsection{Smoothness of the Mukai orders}

\begin{theorem}[\texttt{mukaiOrder\_prime\_factor\_le\_seven}]\label{thm:smooth}
For every $N\in\mukaiOrders$ and every prime $q$ with $q\mid N$, we have $q\le 7$.
\end{theorem}

\begin{proof}[Proof sketch]
Fix $N\in\mukaiOrders$ and a prime $q\mid N$. Since $N>0$, $q\le N$, so $q$ lies in a
finite range; checking each candidate against each of the eleven orders, the only primes
dividing any $N$ are $2,3,5,7$ (consistent with $N\mid 40320=2^7 3^2 5\cdot 7$ from
Theorem~\ref{thm:dvd}). Hence $q\le 7$.
\end{proof}

Equivalently, every Mukai order is a $7$-smooth (i.e. $\{2,3,5,7\}$-) number.

\subsection{Arithmetic tameness}

\begin{theorem}[Arithmetic tameness, \texttt{mukaiOrder\_tame}]\label{thm:tame}
For every prime $p$ with $11<p$ and every $N\in\mukaiOrders$, we have $p\nmid N$.
\end{theorem}

\begin{proof}[Proof sketch]
If $p\mid N$ then $p\le 7$ by Theorem~\ref{thm:smooth}, contradicting $p>11>7$. Hence
$p\nmid N$.
\end{proof}

The hypothesis genuinely used is $p>7$; the conjecture's $p>11$ is not needed for the
arithmetic (see Section~\ref{sec:disc}).

\begin{corollary}[\texttt{mukaiOrder\_coprime}]\label{cor:coprime}
For every prime $p$ with $11<p$ and every $N\in\mukaiOrders$, $\gcd(p,N)=1$.
\end{corollary}

\begin{proof}[Proof sketch]
A prime $p$ is coprime to $N$ iff $p\nmid N$; apply Theorem~\ref{thm:tame}.
\end{proof}

\subsection{Global tameness of the automorphism order}

We combine arithmetic tameness with the characteristic-$p$ tameness of the
non-symplectic index. The latter, denoted
\texttt{nonSymplecticIndex\_not\_dvd\_char}, states $p\nmid[G:G_s]$: the cyclic
quotient $G/G_s\hookrightarrow k^{\times}$ has order prime to $p$ because $k^{\times}$
has no $p$-torsion in characteristic $p$ (the identity $x^{p}-1=(x-1)^{p}$ forces a
$p$-th root of unity to be $1$).

\begin{theorem}[Global tameness, \texttt{aut\_order\_not\_dvd\_char}]\label{thm:global}
Let $k$ be a field of characteristic $p$ with $p$ prime and $11<p$, let $G$ be a finite
group, and let $\chi:G\to k^{\times}$ be a period character. If
$\#G_s=\#\ker\chi\in\mukaiOrders$, then $p\nmid\#G$.
\end{theorem}

\begin{proof}[Proof sketch]
By~\eqref{eq:factor}, $\#G=\#G_s\cdot[G:G_s]$. If $p\mid\#G$ then, $p$ being prime,
Euclid's lemma gives $p\mid\#G_s$ or $p\mid[G:G_s]$. The first contradicts
Theorem~\ref{thm:tame} (as $\#G_s\in\mukaiOrders$ and $p>11$); the second contradicts
\texttt{nonSymplecticIndex\_not\_dvd\_char}. Hence $p\nmid\#G$.
\end{proof}

\begin{corollary}[\texttt{aut\_order\_coprime\_char}]\label{cor:global}
Under the hypotheses of Theorem~\ref{thm:global}, $\gcd(p,\#G)=1$.
\end{corollary}

\begin{proof}[Proof sketch]
For prime $p$, coprimality with $\#G$ is equivalent to $p\nmid\#G$; apply
Theorem~\ref{thm:global}.
\end{proof}

Theorem~\ref{thm:global} is a genuine bridge: both the algebraic identity in
characteristic $p$ and the arithmetic least common multiple $40320$ are load-bearing.

\section{Algorithmic content}

\subsection{Smoothness certification by least common multiple}
To certify a finite list $L=[N_1,\dots,N_m]$ of orders is $B$-smooth, compute
$M=\lcm(L)$, factor the single number $M$, and check $\max(\text{primes of }M)\le B$.
Since each $N_i\mid M$, every prime factor of every $N_i$ divides $M$. For the Mukai
list, $M=40320$, primes $\{2,3,5,7\}$, $B=7$. Cost: one factorization of $M$ plus $m$
divisions.

\subsection{Tameness oracle}
Given $B=7$ and a prime $p$, tameness of the whole list reduces to the single
comparison $p>B$; no per-order divisibility test is required. Synthesis with the index
adds one imported bit ($p\nmid[G:G_s]$), after which Euclid's lemma on~\eqref{eq:factor}
finishes.

\section{Worked numerical examples}
\begin{itemize}
\item \textbf{$p=13$.} $13>11$ and $13\nmid N$ for every Mukai order. With $\#G_s=960$
and $[G:G_s]=5$, $\#G=4800$ and $13\nmid 4800$: global tameness holds.
\item \textbf{$p=7$.} At $p=7$ the smoothness bound is attained:
$7\mid 168$ (since $168=2^3\cdot 3\cdot 7$). So $p=7$ is \emph{not} tame for that order;
arithmetic tameness needs $p>7$.
\item \textbf{The $7$--$11$ gap.} At $p=11$, arithmetic tameness already holds
($11>7$), yet the conjecture excludes $p=11$: the exclusion is not arithmetic.
\end{itemize}

\section{Discussion: the arithmetic/geometry split}\label{sec:disc}
The threshold $p>11$ separates into two mechanisms. The \emph{arithmetic} mechanism is
resolved here: the Mukai orders are $7$-smooth, $\lcm=40320=2^7 3^2 5\cdot 7$, so
tameness of the symplectic order holds for every $p>7$. The \emph{geometric} mechanism
is conjectural: the four-unit gap (primes through $11$) cannot be divisibility, so the
residual obstruction --- $[G:G_s]=1$ for maximal $G_s$ --- must originate in the
cyclotomic action on the rank-$22$ crystalline/N\'eron--Severi lattice. Exhausting the
arithmetic localizes the remaining mystery precisely to characteristics $11$ and below.

\section{Future directions}
\begin{enumerate}
\item \textbf{Geometric rigidity $[G:G_s]=1$ for maximal $G_s$.} By global tameness the
only remaining freedom is a cyclic $C_n\hookrightarrow k^{\times}$ with $\gcd(n,p)=1$;
the obstruction to $n>1$ must come from the invariant-lattice count.
\item \textbf{The $7$-to-$11$ gap is purely geometric.} Tameness holds for $p>7$, so
the no-extension phenomenon should fail for some maximal $G_s$ when $7<p\le 11$, making
$p>11$ sharp.
\item \textbf{Totient bound.} Any realized $n=[G:G_s]$ on a tame K3 in characteristic
$p>11$ should satisfy $\varphi(n)\le 21$, with admissible $n$ compatible with a single
Mukai invariant lattice --- forcing $n=1$ when $G_s$ is maximal.
\item \textbf{Multiplicative tameness as a classification axiom.} Global tameness should
suffice to transport Mukai's characteristic-$0$ classification verbatim to
characteristic $p>11$.
\end{enumerate}

\section{Conclusion}
The eleven Mukai orders are $7$-smooth with least common multiple
$40320=2^7 3^2 5\cdot 7$ (Theorems~\ref{thm:dvd}--\ref{thm:smooth}); hence every prime
$p>11$ (indeed $p>7$) is coprime to every Mukai order (Theorem~\ref{thm:tame},
Corollary~\ref{cor:coprime}). Synthesizing with characteristic-$p$ tameness of the
non-symplectic index yields global tameness of $\#\Aut(X)$ for $p>11$
(Theorem~\ref{thm:global}, Corollary~\ref{cor:global}). The arithmetic is exhausted at
$p>7$, localizing the genuine, conjectural rigidity to the geometric gap between $7$
and $11$.

